import {BUILD_STEPS,SHIFT_HOURS} from './downstream.js';
import {criticalMilestones} from './build-milestones.js';
import {deliveryResults} from './delivery.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const d=x=>x?new Date(x+'T12:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'—';
export function stepTimeSettings(s){return `<section class="card product-lead-link"><div><h3>Lead times by product type</h3><p>Enter hours per 20 sheets for lamination and per 20 cases for other steps. The planner scales these to each order.</p></div><button data-tab="leadTimes">Edit product lead times →</button></section>`;}
export function buildTimeline(s,o,m){
 const noNew=m.complete&&!m.formingStart,formingStart=m.formingStart?d(m.formingStart):noNew?'Opening supply':'Not scheduled',formingFinish=m.formingFinish?d(m.formingFinish):noNew?'No new forming':'Not covered',curedFinish=m.finalCure?d(m.finalCure):m.complete?'Opening stock':'Not covered';
 const reserve=m.startBy?d(m.startBy):noNew?'No new forming':m.complete?'Use planned start':'Not confirmed';
 const startTone=!m.complete?'red':m.startBy&&m.formingStart>m.startBy?'amber':'green',startText=!m.complete?'Build not fully covered':m.startBy&&m.formingStart>m.startBy?'Review forming sequence':noNew?'Covered by opening supply':'Planned start meets estimate';
 const route=m.downstream?.steps||[];
 return `<section class="build-timing" aria-label="${esc(o.part)} ${o.week} build dates"><div class="build-start-grid"><div><span>Start forming by · estimate</span><strong>${reserve}</strong></div><div><span>Planned forming start</span><strong>${formingStart}</strong></div></div><div class="timing-status ${startTone}">${startText}</div><p class="timing-note">${m.startBy?'The estimate reserves whole carts backward while holding other production fixed. It preserves the first required release from each cart and all oven, forming and holiday limits. The reserve sequence is an alternative, not an applied schedule or a proven latest possible start.':noNew?'This build uses opening cured stock and/or carts already in the oven. Their forming start is outside this forecast.':'A reliable start-by estimate needs a complete, valid plan. Check uncovered demand, the plan horizon and opening-cart conflicts.'}${m.sharedFixed?' Manual loads and carts shared with other orders keep their planned dates.':''}</p>
 <h4>Step-by-step forecast</h4><div class="scroll"><table class="build-step-table"><thead><tr><th>Step</th><th>First start</th><th>Final finish / available</th></tr></thead><tbody>
 <tr><td><strong>Akro forming</strong><small>${m.openingPanels?`${m.openingPanels} sheets supplied from opening inventory / oven`:'New production supplying this group'}</small></td><td>${formingStart}</td><td>${formingFinish}</td></tr>
 <tr><td><strong>Akro oven</strong><small>${s.settings[o.kind+'Cure']} calendar days per cart · unload at full cure</small></td><td>${d((o.allocations||[]).filter(a=>a.loadDate).map(a=>a.loadDate).sort()[0])}</td><td>${curedFinish}</td></tr>
 <tr><td><strong>20-sheet pulls from supermarket</strong><small>The next pull waits until waterjet finishes the current batch</small></td><td>${d(m.firstRelease)}</td><td>${d(m.finalRelease)}</td></tr>
 ${BUILD_STEPS.map(([key,label])=>{const step=route.find(x=>x.key===key),hours=o.route.hours[key],rate=o.route.rateDetails?.[key];return `<tr class="${step?'':'unconfirmed-step'}"><td><strong>${label}</strong><small>${hours==null?(o.route.needsCases&&rate?.basis==='cases'?'Enter order cases in Weekly demand':'Enter batch time'):`${hours} working hours${hours===0?' · bypassed':''}`}${rate?` · ${rate.rate}h / 20 ${rate.basis} × ${rate.quantity} ${rate.basis}`:''}</small></td><td>${hours===0?'Bypassed':step?d(step.start):o.route.complete?'Awaiting batch':'Not set'}</td><td>${hours===0?'Bypassed':step?.finish?d(step.finish):step?'Remaining batches pending':o.route.complete?'Awaiting batch':'Not set'}</td></tr>`}).join('')}
 <tr><td><strong>Whole order ready to ship</strong><small>${o.route.complete?'After the final batch clears QC':'Calendar-day estimate if lead time is entered'}</small></td><td>—</td><td>${d(m.downstream?.finish||o.projected)}</td></tr>
 </tbody></table></div>${!o.route.complete?'<p class="timing-note amber-text">Batch dates need all effective step times and any required case quantities. The existing total delivery allowance remains in use until the route is complete.</p>':'<p class="timing-note">Each 20-sheet batch moves forward independently; the final order remainder can contain fewer whole sheets. Critical batches can start as cured stock arrives within the 28-day priority window. The waterjet requests one batch when it is free. If lamination is required, that batch is prepared before cutting. Unpulled sheets stay in inventory. One shared lane per step queues all orders with complete routes; different steps can run at the same time. Missing routes do not reserve downstream capacity. Holidays pause all steps; shutdowns pause waterjet. Case-based work is allocated in proportion to each batch’s share of sheets.</p>'}${batchTable(m.downstream)}</section>`;
}
function batchTable(flow){
 if(!flow?.batches.length)return '';
 const pullTime=b=>{
  const minutes=Math.round((b.steps[0].startTime%SHIFT_HOURS)*60);
  return minutes?` · +${Math.floor(minutes/60)}:${String(minutes%60).padStart(2,'0')} into shift`:' · shift start';
 };
 return `<details class="batch-flow-detail"><summary>20-sheet batch forecast · ${flow.batches.length} / ${flow.expectedBatches} batches released</summary><div class="scroll"><table class="batch-flow-table"><thead><tr><th>Batch</th><th>Sheets</th><th>Withdrawn</th>${BUILD_STEPS.map(([,label])=>`<th>${label}<small>Start → finish</small></th>`).join('')}</tr></thead><tbody>${flow.batches.map(b=>`<tr><td>${b.index}</td><td>${b.sheets}</td><td>${d(b.release)}${pullTime(b)}</td>${b.steps.map(x=>`<td>${x.skipped?'Bypassed':`${d(x.start)} → ${d(x.finish)}`}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;
}
export function milestoneCsv(s,rows){
 const milestones=criticalMilestones(s,rows),projected=new Map(deliveryResults(rows).map(o=>[o.id,o.projected])),cell=x=>'"'+String(x??'').replaceAll('"','""')+'"';
 const header=['Part','Week','Required_panels','Start_by_estimate','Planned_forming_start','Forming_finish','Oven_finish','First_Akro_release','Final_Akro_release',...BUILD_STEPS.flatMap(([key])=>[key+'_start',key+'_finish']), 'Ready_to_ship_target','Projected_ready_to_ship','Complete_Akro_plan','Downstream_step_times_complete'];
 const data=(rows.orderResults||[]).filter(o=>o.priority==='critical').map(o=>{const m=milestones.get(o.id);return [o.part,o.week,o.total,m.startBy,m.formingStart,m.formingFinish,m.finalCure,m.firstRelease,m.finalRelease,...BUILD_STEPS.flatMap(([key])=>{const step=m.downstream?.steps.find(x=>x.key===key);return [step?.start,step?.finish]}),o.target,m.downstream?.finish||projected.get(o.id),m.complete,o.route.complete];});
 return [header,...data].map(row=>row.map(cell).join(',')).join('\n');
}
